from pathlib import Path
import shutil, hashlib
root=Path.cwd()
src=Path('C:/Users/Projeto Guedala Park/Downloads/memorial_descritivo.pdf')
dest=root/'02_Plantas_e_manuais/Memorial_descritivo_Cury_Guedala_Park_III_R00_2023-04-03.pdf'
if dest.exists() and dest.read_bytes()!=src.read_bytes(): raise RuntimeError('Destino já existe com outro conteúdo')
shutil.copy2(src,dest)
assert hashlib.sha256(src.read_bytes()).digest()==hashlib.sha256(dest.read_bytes()).digest()
changed=[]
def edit(name,func):
 p=root/name;s=p.read_text(encoding='utf-8');v=func(s)
 if v!=s:p.write_text(v,encoding='utf-8');changed.append(name)
def after_title(s,note):
 a,b=s.split('\n',1);return a+'\n\n'+note+'\n'+b
note='**Atualização documental F101 — 12/09/2026:** memorial oficial recebido e arquivado. Consultar [entrega e impactos no projeto](../Memorial_Cury_entrega_e_impactos.md).'
sector={
'Cozinha':'Entrega com bancada de pedra natural e cuba inox; Dora, Apurema e Branco Itaúnas são reforma planejada. Cozinha sem ralo e sem impermeabilização prevista; há ponto para depurador, sem infraestrutura para coifa. Tomadas indicadas como “110V” no memorial; circuitos específicos ainda pendentes.',
'Lavanderia':'Ponto e tubulação de aquecimento a gás para o chuveiro confirmados; aquecedor e chuveiro não fornecidos. Tanque entregue em mármore sintético ou louça; tanque esculpido é reforma. Piso impermeabilizado, sanca e shaft a compatibilizar com varal e aquecedor.',
'Equipamentos':'O memorial informa tomadas predefinidas como “110V” e restrição à alteração de tensão; confirmar circuitos antes das compras. Aquecedor e chuveiro não fornecidos; modelo do aquecedor segue pendente. Ar-condicionado tem instalação expressamente proibida pelo documento. Escolhas de aparelhos preservadas.',
'Escritorio':'Quarto entregue com laminado e acabamento de teto diretamente na laje. Gesso e tratamento acústico/térmico são reforma pretendida; 2,57 m de entrega e 2,47 m finais seguem cenários sem confirmação dimensional. Projeto elétrico e fixações permanecem pendentes; memorial proíbe instalação de ar-condicionado.',
'Portas_e_quarto':'Alvenaria estrutural e restrições a aberturas, demolições e alterações de pontos constam na p. 14. Portas originais permanecem base; estudos anteriores não comprovam permissão para intervenções.',
'Medidas':'Memorial confirma acabamentos e infraestrutura prevista, mas não informa pé-direito, dimensões de sancas, janelas ou posições cotadas dos pontos. As cotas das plantas são de face a face com acabamento; não são levantamento da unidade.'}
for folder,body in sector.items():edit(f'01_Projeto/{folder}/README.md',lambda s,body=body:after_title(s,note+' '+body))
edit('02_Plantas_e_manuais/README.md',lambda s:s.replace('- [Planta oficial]', '- [Memorial oficial Cury — Guedala Park III, R00 de 03/04/2023](Memorial_descritivo_Cury_Guedala_Park_III_R00_2023-04-03.pdf): documento de entrega recebido do portal em 12/09/2026, preservado sem edição. [Leitura e impactos no projeto](../01_Projeto/Memorial_Cury_entrega_e_impactos.md).\n- [Planta oficial]').replace(': base de escolhas,', ': memorial de escolhas de interiores de Elias, distinto do memorial oficial de entrega;'))
edit('README.md',lambda s:s.replace('| Decisões e suas fontes |','| Entrega da Cury e efeitos na reforma | [Memorial oficial e análise](01_Projeto/Memorial_Cury_entrega_e_impactos.md) |\n| Decisões e suas fontes |').replace('[Relatório com plantas](output/pdf/Pesquisa_Cury_40m2.pdf)','[Relatório com plantas — anterior ao memorial](output/pdf/Pesquisa_Cury_40m2.pdf)').replace('Os estudos partem da planta e de imagens de uma unidade espelhada.','Os estudos partem da planta, do memorial oficial de entrega da Cury (R00, 03/04/2023) e de imagens de uma unidade espelhada.'))
edit('01_Projeto/Resumo.md',lambda s:s.replace('## Escolhas por ambiente','## Entrega confirmada no memorial oficial\n\n[Memorial Cury e impactos — F101](Memorial_Cury_entrega_e_impactos.md), recebido em 12/09/2026. Sala, circulação e cozinha com piso em laje acabada; quartos com laminado; banheiro e lavanderia com piso cerâmico e impermeabilização. Banheiro com forro, cozinha/lavanderia com sancas; quartos e sala com acabamento sobre laje. Alturas e posições exatas continuam pendentes.\n\nInfraestrutura de aquecimento a gás do chuveiro prevista; aquecedor e chuveiro não fornecidos. O memorial proíbe instalação de ar-condicionado nas unidades, menciona tomadas predefinidas como “110V”, prevê ponto para depurador e exclui infraestrutura de coifa e ralo na cozinha. Alterações de pontos e paredes têm restrições documentais.\n\nBancada Branco Itaúnas, cuba Dora, Apurema, tanque esculpido, metais escuros e gesso adicional permanecem escolhas de reforma; não são itens confirmados de entrega. Revisão posterior do memorial, circuitos, cortes e esquadrias ainda a consultar.\n\n## Escolhas por ambiente').replace('Revestimentos registrados no memorial e no registro.','Revestimentos de reforma registrados no memorial de interiores e no registro.'))
edit('01_Projeto/Registro_de_decisoes.md',lambda s:s.replace('**Precedência:** correções explícitas atuais de Elias prevalecem; o memorial é a base das escolhas,','**Precedência das escolhas:** correções explícitas atuais de Elias prevalecem; o memorial de interiores v2 é a base das escolhas,').replace('## 2. Pendências conciliadas','**Fonte de entrega — F101:** [memorial oficial Cury e impactos](Memorial_Cury_entrega_e_impactos.md). Especificações de entrega e restrições documentais são separadas das escolhas de reforma; estas não aprovam intervenções.\n\n## 2. Pendências conciliadas').replace('| P-003 | Aquecedor sem modelo fechado; GN e ducha já escolhidos |','| P-003 | Aquecedor sem modelo fechado; infraestrutura de gás para chuveiro confirmada por F101, aparelhos não fornecidos; GN e ducha já escolhidos |').replace('| P-007 | Infraestrutura elétrica e iluminação executiva pendentes | Manter intenções; validar cargas e pontos quando houver documentação/acesso. |','| P-007 | Memorial F101 indica tomadas “110V” predefinidas e restrições de alteração; circuitos e iluminação executiva pendentes | Validar cargas, tensões por ponto e intervenções compatíveis antes de comprar/instalar. |')+'\n\n### F101 — Memorial oficial de entrega incorporado ao projeto\n\nEm 12/09/2026, Elias forneceu o memorial do portal Cury e solicitou incluí-lo e atualizar o projeto. Original de 19 páginas, Guedala Park III, R00 de 03/04/2023, preservado em [Plantas e manuais](../02_Plantas_e_manuais/Memorial_descritivo_Cury_Guedala_Park_III_R00_2023-04-03.pdf). [Análise vigente](Memorial_Cury_entrega_e_impactos.md) identifica entrega por ambiente e páginas de origem. Pendência de obter memorial oficial encerrada; manual do proprietário previsto com as chaves.\n\nConfirmados no documento: laminado nos quartos, laje acabada como piso de sala/circulação/cozinha, cerâmica e impermeabilização no banho/lavanderia; forro no banho e sancas na cozinha/lavanderia; bancada de pedra natural e cuba inox na cozinha; ponto/tubulação de aquecimento a gás dos chuveiros, sem fornecimento de aquecedor ou chuveiro. Sem confirmação de água quente nas torneiras.\n\nRestrições: proibição expressa de ar-condicionado; tomadas descritas como “110V”, sem alteração de tensão segundo texto; sem ralo na cozinha ou infraestrutura de coifa, com ponto de depurador; alvenaria estrutural e limitações a alterações. Não tratar equipamentos escolhidos, mudanças de pontos ou portas como instalação aprovada.\n\nPreservadas escolhas de reforma, inclusive gesso/lã e cenário final de 2,47 m. Altura real de 2,57 m e montagem em 10 cm continuam hipóteses. Faltam cortes, forros cotados, esquadrias, circuitos e instalações do final 06. Revisão posterior à R00 não verificada. O memorial de interiores v2 mantém sua função de escolhas; não é documento Cury.\n')
edit('01_Projeto/Pesquisa_pe_direito_R01.md',lambda s:after_title(s,'**Atualização F101 — 12/09/2026:** o [memorial oficial Cury](Memorial_Cury_entrega_e_impactos.md) foi recebido. Confirma pintura/textura na laje do dormitório tipo, mas não informa altura. A pesquisa abaixo é anterior ao recebimento; 2,57 m e 2,47 m continuam hipóteses.').replace('O memorial local é um memorial de decisões do nosso projeto, não o memorial técnico de entrega da construtora.','Na pesquisa original havia apenas o memorial de decisões; o memorial oficial foi incorporado em F101, sem resolver a cota vertical.'))
edit('01_Projeto/Pesquisa_comparativa_Cury/Pesquisa_Cury_40m2.md',lambda s:after_title(s,'**Atualização F101 — 12/09/2026:** memorial oficial recebido após esta pesquisa. Para entrega e instalações, consultar [análise vigente](../Memorial_Cury_entrega_e_impactos.md). A pendência de obtê-lo está encerrada; a proibição de ar-condicionado e a infraestrutura de gás para chuveiro estão documentadas. O texto abaixo e o PDF preservam a pesquisa anterior; altura e plantas técnicas permanecem pendentes.'))
print('Cópia idêntica SHA-256:',hashlib.sha256(dest.read_bytes()).hexdigest())
print('\n'.join(changed))
